/**
 * Optional HTTPS listener for the sidecar.
 *
 * Office add-ins must be served over HTTPS, so the Word task pane loads from
 * https://localhost:<tlsPort>/word/taskpane.html — the same Express app as the
 * plain listener, which keeps the AI API and the /events websocket
 * same-origin for the pane. The cert is a locally trusted self-signed
 * certificate generated by `npm run word:setup` (see docs/word-addin.md).
 *
 *   WRITER_TLS=0                 disable the listener
 *   WRITER_TLS_PORT=8443         port (default 8443)
 *   WRITER_TLS_CERT / _KEY       PEM paths (default ~/.nebula-writer/certs/localhost{,-key}.pem)
 */

import { existsSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

export const DEFAULT_TLS_PORT = 8443;

export interface TlsConfig {
  certPath: string;
  keyPath: string;
  port: number;
}

export function defaultTlsCertDir(env: NodeJS.ProcessEnv = process.env): string {
  return env.WRITER_TLS_DIR?.trim() || join(env.WRITER_HOME?.trim() || join(homedir(), ".nebula-writer"), "certs");
}

/** Resolve the TLS listener config, or null when disabled or no cert material exists. */
export function resolveTlsConfig(env: NodeJS.ProcessEnv = process.env): TlsConfig | null {
  if (["0", "false", "off", "no"].includes((env.WRITER_TLS ?? "").trim().toLowerCase())) {
    return null;
  }
  const dir = defaultTlsCertDir(env);
  const certPath = env.WRITER_TLS_CERT?.trim() || join(dir, "localhost.pem");
  const keyPath = env.WRITER_TLS_KEY?.trim() || join(dir, "localhost-key.pem");
  if (!existsSync(certPath) || !existsSync(keyPath)) {
    return null;
  }
  const parsedPort = Number.parseInt(env.WRITER_TLS_PORT ?? "", 10);
  const port = Number.isSafeInteger(parsedPort) && parsedPort > 0 && parsedPort < 65_536 ? parsedPort : DEFAULT_TLS_PORT;
  return { certPath, keyPath, port };
}

export function readTlsMaterial(config: TlsConfig): { cert: Buffer; key: Buffer } {
  return { cert: readFileSync(config.certPath), key: readFileSync(config.keyPath) };
}
